using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Account;
public class RegisterModel:PageModel {private readonly IHttpClientFactory _factory;[BindProperty]public RegisterInput Input{get;set;}=new();public RegisterModel(IHttpClientFactory factory)=>_factory=factory;public async Task<IActionResult> OnPostAsync(){if(Input.Password.Length<6){ModelState.AddModelError("","Паролата трябва да е поне 6 символа.");return Page();}var r=await _factory.CreateClient("SportRaceApi1").PostAsJsonAsync("api/users/register",Input);if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Неуспешна регистрация. Възможно е e-mail адресът вече да се използва.");return Page();}return RedirectToPage("Login");}public class RegisterInput{public string FirstName{get;set;}="";public string LastName{get;set;}="";public string Email{get;set;}="";public string Password{get;set;}="";}}
